pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 diff1, uint256 diff2) public {
        // 1. Bound timestamps to reasonable range and differences to non-zero to avoid modulo issues
        vm.assume(timestamp1 != timestamp2);
        vm.assume(diff1 != 0 && diff2 != 0);
        // 2. Execute two separate play calls with different block parameters
        address player = address(0x123);
        vm.deal(player, 100 ether);

        // First play - warp to timestamp1 and set difficulty to diff1
        vm.warp(timestamp1);
        vm.roll(diff1);
        vm.prank(player);
        c.play{value: 10}();

        uint256 potAfterFirst = c.pot();
        uint256 balanceAfterFirst = address(c).balance;

        // Second play - warp to timestamp2 and set difficulty to diff2
        vm.warp(timestamp2);
        vm.roll(diff2);

        // Record pot before second play
        uint256 potBeforeSecond = c.pot();
        uint256 balanceBeforeSecond = address(c).balance;

        vm.prank(player);
        c.play{value: 10}();

        uint256 potAfterSecond = c.pot();
        uint256 balanceAfterSecond = address(c).balance;

        // 3. The invariant: pot must equal total contributed (20) minus total paid out by contract.
        // Track payouts by monitoring balance changes on player side and contract side.
        // Simpler: assert that pot equals total tickets (20) minus total payouts.
        // After two plays with no wins, pot should be 20; after one win, pot should be reset to 0 in reference.
        // The general rule: pot <= total tickets contributed (20) AND if a win occurred (balance decreased by >10), pot == 0.
        // But we need a single assertion that always holds for reference and fails for buggy.
        // The correct invariant: After any sequence, pot = total contributed - total_paid_out.
        // We compute total_paid_out as original player balance minus current player balance minus any unspent gas? No.
        // Instead, track total_paid_out by checking contract balance changes.
        // Total contributed is 20 wei (two tickets).
        // If contract paid out, total_paid_out = 20 - address(c).balance.
        // Then pot should equal total contributed - total_paid_out = address(c).balance.
        // Thus the invariant: pot == address(c).balance.
        // Let's verify: Reference: after win, pot=0, balance=0 (since 10 goes to bank fee, 10 to player? Wait: pot increases by 10 each play.
        // Actually, pot increases by 10 each play. On win, bank gets 1, player gets pot-1. Then pot resets to 0.
        // After first play (no win): pot=10, balance=10.
        // After second play (win): pot=10+10=20, win triggered -> bank gets 1, player gets 19, pot=0, balance=0. So pot==balance holds.
        // After two wins in a row? Reference: play1 win -> pot=0, balance=0; play2: pot=10, win -> pot=20, bank=1, player=19, pot=0, balance=0. pot==balance holds.
        // Buggy: after second win, pot not reset, so pot=20, but balance=0. pot != balance. Thus invariant: pot == address(c).balance is always true for reference, broken for buggy.
        assertTrue(c.pot() == address(c).balance);
    }
}

